on = {x for x, y in zip(xs, ys) if y}
off = {x for x, y in zip(xs, ys) if not y}

# Quine–McCluskey: cube entries are 0, 1, or None.
cubes = {(x, 0) for x in on}  # (bits, don't-care mask)
primes = set()
while cubes:
    groups = {}
    for bits, mask in cubes:
        groups.setdefault((mask, sum((bits[i] >> i) & 1 for i in range(10)
