                other_bits = list(bits)
                other_bits[i] ^= 1
                other = (tuple(other_bits), mask)
                if other in group:
                    used.add((bits, mask))
                    used.add(other)
                    new_bits = list(bits)
                    new_bits[i] = 0
                    new_mask = list(mask)
                    new_mask[i] = True
                    combined.add((tuple(new_bits), tuple(new_mask)))
    primes.update(cubes - used)
    cubes = combined

