spec = TASK["public"]["specification"]
ys = list(map(int, spec["outputs"]))
assert len(ys) == 1024

# Inspect algebraic and Shannon structure of the public truth table.
def cof(var, value, table):
    return [table[i] for i in range(1024)
            if ((i >> (9 - var)) & 1) == value]

influences = []
for v in range(10):
    a, b = cof(v, 0, ys), cof(v, 1, ys)
    influences.append(sum(x != y for x, y in zip(a, b)))

anf = ys[:]
for bit in range(10):
    step = 1 << bit
    for i in range(1024):
        if i & step:
            anf[i] ^= anf[i ^ step]
degree = max((i.bit_count() for i, c in enumerate(anf) if c), default=-1)

# Count unique residual truth tables in the reduced ordered BDD, by level.
levels = []
for depth in range(11):
    width = 1 << (10 - depth)
    residuals = {tuple(ys[k:k + width]) for k in range(0, 1024, width)}
    levels.append(len(residuals))

print({
    "ones": sum(ys),
    "influence_counts_by_input_0_to_9": influences,
    "anf_degree": degree,
    "distinct_residual_functions_by_prefix_depth": levels,
})
